use std::collections::BTreeSet;
pub fn sequence(n:usize,edges:&[(usize,usize)])->Vec<usize>{
    let mut remaining:BTreeSet<_>=(0..n).collect();
    let(mut head,mut tail)=(Vec::new(),Vec::new());
    while !remaining.is_empty(){
        let degrees:Vec<_>=remaining.iter().map(|&v|{
            let out=edges.iter().filter(|&&(a,b)|a==v&&remaining.contains(&b)).count();
            let incoming=edges.iter().filter(|&&(a,b)|b==v&&remaining.contains(&a)).count();
            (v,out,incoming)
        }).collect();
        let chosen=if let Some(&(v,_,_))=degrees.iter().find(|(_,out,_)|*out==0){
            tail.insert(0,v);
            v
        }else if let Some(&(v,_,_))=degrees.iter().find(|(_,_,incoming)|*incoming==0){
            head.push(v);
            v
        }else{
            let &(v,_,_)=degrees.iter().min_by_key(|&&(v,out,incoming)|(std::cmp::Reverse(out as i64-incoming as i64),v)).unwrap();
            head.push(v);
            v
        };
        remaining.remove(&chosen);
    }
    head.extend(tail);
    head
}
pub struct Layering{
    pub heights:Vec<i64>,
    pub labels:Vec<usize>,
    pub before:i64,
    pub rounds:usize,
    pub promotions:Vec<(usize,usize,i64)>
}
pub fn assign(n:usize,edges:&[(usize,usize)],coffman:bool,width:usize,promotion:bool)->Layering{
    let mut upper=vec![Vec::new();n];
    let mut lower=vec![Vec::new();n];
    for &(a,b)in edges{
        upper[b].push(a);
        lower[a].push(b);
    }
    for a in &mut upper{
        a.sort();
    }
    for a in &mut lower{
        a.sort();
    }
    let mut labels=vec![0;n];
    let mut heights=vec![-1;n];
    if coffman{
        for k in 1..=n{
            let v=(0..n).filter(|&v|labels[v]==0&&upper[v].iter().all(|&u|labels[u]>0)).min_by_key(|&v|{
                let mut key:Vec<_>=upper[v].iter().map(|&u|labels[u]).collect();
                key.sort_by(|a,b|b.cmp(a));
                (key,v)
            }).unwrap();
            labels[v]=k;
        }
        let(mut current,mut count)=(0,0);
        for _ in 0..n{
            let v=(0..n).filter(|&v|heights[v]<0&&lower[v].iter().all(|&u|heights[u]>=0)).max_by_key(|&v|labels[v]).unwrap();
            if count==width||lower[v].iter().any(|&u|heights[u]==current){
                current+=1;
                count=0;
            }
            heights[v]=current;
            count+=1;
        }
    }else{
        fn height(v:usize,lower:&[Vec<usize>],heights:&mut[i64])->i64{
            if heights[v]>=0{
                return heights[v];
            }
            let mut h=0;
            for &u in &lower[v]{
                h=h.max(height(u,lower,heights)+1);
            }
            heights[v]=h;
            h
        }
        for v in 0..n{
            height(v,&lower,&mut heights);
        }
    }
    let before=edges.iter().map(|&(a,b)|heights[a]-heights[b]-1).sum();
    let mut rounds=0;
    let mut promotions=Vec::new();
    if promotion{
        fn promote(v:usize,upper:&[Vec<usize>],lower:&[Vec<usize>],h:&mut[i64])->i64{
            let mut diff=0;
            for &u in &upper[v]{
                if h[u]==h[v]+1{
                    diff+=promote(u,upper,lower,h);
                }
            }
            h[v]+=1;
            diff+lower[v].len()as i64-upper[v].len()as i64
        }
        loop{
            rounds+=1;
            let mut changed=false;
            for v in 0..n{
                if upper[v].is_empty(){
                    continue;
                }
                let saved=heights.clone();
                let diff=promote(v,&upper,&lower,&mut heights);
                if diff<0{
                    promotions.push((rounds,v,diff));
                    changed=true;
                }else{
                    heights=saved;
                }
            }
            if !changed{
                break;
            }
        }
    }
    Layering{
        heights,
        labels,
        before,
        rounds,
        promotions
    }
}

pub struct Canvas{
    pub main:usize,
    pub direction:String,
    pub rows:usize,
    pub columns:usize,
    lines:Vec<Vec<u8>>,
    arrows:Vec<Vec<Option<char>>>,
    boxes:Vec<Vec<Option<char>>>,
    highlight:Vec<Vec<bool>>
}
impl Canvas{
    pub fn new(main:usize,secondary:usize,direction:&str)->Self{
        let vertical=direction=="TB"||direction=="BT";
        let(rows,columns)=if vertical{
            (main,secondary)
        }else{
            (secondary,main)
        };
        Self{
            main,
            direction:direction.into(),
            rows,
            columns,
            lines:vec![vec![0;columns];rows],
            arrows:vec![vec![None;columns];rows],
            boxes:vec![vec![None;columns];rows],
            highlight:vec![vec![false;columns];rows]
        }
    }
    pub fn map(&self,m:usize,c:usize)->(usize,usize){
        let m=if self.direction=="BT"||self.direction=="RL"{
            self.main-1-m
        }else{
            m
        };
        if self.direction=="TB"||self.direction=="BT"{
            (m,c)
        }else{
            (c,m)
        }
    }
    pub fn line(&mut self,m:usize,c:usize,main:bool){
        let(row,column)=self.map(m,c);
        let vertical=self.direction=="TB"||self.direction=="BT";
        self.lines[row][column]|=if main==vertical{
            1
        }else{
            2
        };
    }
    pub fn corner(&mut self,m:usize,c:usize){
        let(row,column)=self.map(m,c);
        self.lines[row][column]|=4;
    }
    pub fn arrow(&mut self,m:usize,c:usize,reversed:bool){
        let(row,column)=self.map(m,c);
        let a=match(self.direction.as_str(),reversed){
            ("TB",false)|("BT",true)=>'v',("TB",true)|("BT",false)=>'^',("LR",false)|("RL",true)=>'>',_=>'<'
        };
        self.arrows[row][column]=Some(a);
    }
    pub fn highlight(&mut self,row:usize,column:usize){
        self.highlight[row][column]=true;
    }
    pub fn label(&mut self,row:usize,column:usize,label:&str){
        for(i,c)in label.chars().enumerate(){
            self.boxes[row][column+i]=Some(c);
        }
    }
    pub fn crossings(&self)->usize{
        self.lines.iter().flat_map(|r|r.iter()).filter(|&&c|c&3==3).count()
    }
    pub fn report(&self)->Vec<String>{
        let mut lines=vec![format!("    {}",(0..self.columns).map(|c|(b'0'+(c%10)as u8)as char).collect::<String>())];
        for row in 0..self.rows{
            let mut line=format!("{:3} ",row);
            for column in 0..self.columns{
                let bits=self.lines[row][column];
                let c=if let Some(c)=self.boxes[row][column]{
                    c
                }else if let Some(c)=self.arrows[row][column]{
                    c
                }else if self.highlight[row][column]{
                    '#'
                }else{
                    match bits{
                        0=>' ',1=>'|',2=>'-',_=>'+'
                    }
                };
                line.push(c);
            }
            lines.push(line.trim_end().to_string());
        }
        lines
    }
}

use std::collections::{BTreeMap,BTreeSet};
use crate::crossing;
pub struct Coordinates{
    pub x:Vec<i64>,
    pub aligned:Vec<Vec<i64>>,
    pub blocks:Vec<usize>,
    pub widths:Vec<i64>,
    pub smallest:usize,
    pub conflicts:usize,
    pub left:Vec<i64>,
    pub right:Vec<i64>
}
fn pair(a:usize,b:usize)->(usize,usize){
    (a.min(b),a.max(b))
}
pub fn assign(n:usize,order:&[Vec<usize>],layer:&[usize],upper:&[Vec<usize>],lower:&[Vec<usize>],width:&[i64],vertical:bool,node_sep:i64,dummy_sep:i64)->Coordinates{
    let vertices=layer.len();
    let pos=crossing::positions(order,vertices);
    let left:Vec<_>=width.iter().map(|&w|if vertical{
        (w-1)/2
    }else{
        0
    }).collect();
    let right:Vec<_>=width.iter().zip(&left).map(|(&w,&l)|if vertical{
        w-1-l
    }else{
        0
    }).collect();
    let separation=|a:usize,b:usize|right[a]+left[b]+1+if a<n&&b<n{
        node_sep
    }else{
        dummy_sep
    };
    let mut marked=BTreeSet::new();
    for i in 0..order.len().saturating_sub(1){
        let(a,b)=(&order[i],&order[i+1]);
        let(mut k0,mut t)=(0,0);
        for l1 in 0..b.len(){
            let v=b[l1];
            let inner=v>=n&&upper[v][0]>=n;
            if inner||l1+1==b.len(){
                let k1=if inner{
                    pos[upper[v][0]]
                }else{
                    a.len()-1
                };
                for l in t..=l1{
                    let w=b[l];
                    for &u in &upper[w]{
                        if pos[u]<k0||pos[u]>k1{
                            marked.insert(pair(u,w));
                        }
                    }
                }
                t=l1+1;
                k0=k1;
            }
        }
    }
    let mut layouts=Vec::new();
    let mut blocks=Vec::new();
    let mut widths=Vec::new();
    let mut lows=Vec::new();
    let mut highs=Vec::new();
    for variant in 0..4{
        let down=variant>=2;
        let right_scan=variant%2==1;
        let q=|v:usize|if right_scan{
            order[layer[v]].len()-1-pos[v]
        }else{
            pos[v]
        };
        let mut root:Vec<_>=(0..vertices).collect();
        let mut align=root.clone();
        let mut layers:Vec<_>=(0..order.len()).collect();
        if down{
            layers.reverse();
        }
        for &i in layers.iter().skip(1){
            let mut scan=order[i].clone();
            if right_scan{
                scan.reverse();
            }
            let mut rho=-1i64;
            for v in scan{
                let mut reference=if down{
                    lower[v].clone()
                }else{
                    upper[v].clone()
                };
                reference.sort_by_key(|&u|q(u));
                if reference.is_empty(){
                    continue;
                }
                for m in [(reference.len()-1)/2,reference.len()/2].iter().copied(){
                    let u=reference[m];
                    if align[v]==v&&!marked.contains(&pair(u,v))&&rho<(q(u)as i64){
                        align[u]=v;
                        root[v]=root[u];
                        align[v]=root[v];
                        rho=q(u)as i64;
                    }
                }
            }
        }
        let roots:BTreeSet<_>=root.iter().copied().collect();
        blocks.push(roots.len());
        let mut edges:BTreeMap<(usize,usize),i64>=BTreeMap::new();
        for row in order{
            let mut scan=row.clone();
            if right_scan{
                scan.reverse();
            }
            for w in scan.windows(2){
                let(a,b)=(w[0],w[1]);
                let delta=if right_scan{
                    separation(b,a)
                }else{
                    separation(a,b)
                };
                edges.entry((root[a],root[b])).and_modify(|d|*d=(*d).max(delta)).or_insert(delta);
            }
        }
        let mut incoming=vec![Vec::new();vertices];
        let mut outgoing=vec![Vec::new();vertices];
        let mut degree=vec![0usize;vertices];
        for(&(a,b),&d)in &edges{
            incoming[b].push((a,d));
            outgoing[a].push((b,d));
            degree[b]+=1;
        }
        let mut ready:BTreeSet<_>=roots.iter().copied().filter(|&r|degree[r]==0).collect();
        let mut topology=Vec::new();
        while let Some(v)=ready.pop_first(){
            topology.push(v);
            for &(u,_)in &outgoing[v]{
                degree[u]-=1;
                if degree[u]==0{
                    ready.insert(u);
                }
            }
        }
        let mut y1=vec![0i64;vertices];
        for &v in &topology{
            y1[v]=incoming[v].iter().map(|&(u,d)|y1[u]+d).max().unwrap_or(0);
        }
        let mut y2=y1.clone();
        for &v in topology.iter().rev(){
            if let Some(minimum)=outgoing[v].iter().map(|&(u,d)|y2[u]-d).min(){
                y2[v]=y1[v].max(minimum);
            }
        }
        let x:Vec<_>=root.iter().map(|&r|if right_scan{
            -y2[r]
        }else{
            y2[r]
        }).collect();
        let lo=(0..vertices).map(|v|x[v]-left[v]).min().unwrap();
        let hi=(0..vertices).map(|v|x[v]+right[v]).max().unwrap();
        lows.push(lo);
        highs.push(hi);
        widths.push(hi-lo+1);
        layouts.push(x);
    }
    let smallest=(0..4).min_by_key(|&i|(widths[i],i)).unwrap();
    for i in 0..4{
        let delta=if i%2==0{
            lows[smallest]-lows[i]
        }else{
            highs[smallest]-highs[i]
        };
        for x in &mut layouts[i]{
            *x+=delta;
        }
    }
    let mut x=Vec::new();
    for v in 0..vertices{
        let mut values:Vec<_>=layouts.iter().map(|l|l[v]).collect();
        values.sort();
        x.push((values[1]+values[2]).div_euclid(2));
    }
    let minimum=(0..vertices).map(|v|x[v]-left[v]).min().unwrap();
    for x in &mut x{
        *x-=minimum;
    }
    Coordinates{
        x,
        aligned:layouts,
        blocks,
        widths,
        smallest,
        conflicts:marked.len(),
        left,
        right
    }
}

#[derive(Clone)] pub struct Segment{
    pub p:usize,
    pub q:usize,
    pub edge:usize
}
pub fn positions(order:&[Vec<usize>],n:usize)->Vec<usize>{
    let mut pos=vec![0;n];
    for layer in order{
        for(i,&v)in layer.iter().enumerate(){
            pos[v]=i;
        }
    }
    pos
}
pub fn count(segments:&[Segment],pos:&[usize],width:usize)->usize{
    let mut pairs:Vec<_>=segments.iter().map(|s|(pos[s.p],pos[s.q])).collect();
    pairs.sort();
    let mut c=1;
    while c<width{
        c*=2;
    }
    let mut tree=vec![0usize;2*c-1];
    let mut count=0;
    for(_,q)in pairs{
        let mut k=q+c-1;
        tree[k]+=1;
        while k>0{
            if k%2==1{
                count+=tree[k+1];
            }
            k=(k-1)/2;
            tree[k]+=1;
        }
    }
    count
}
pub fn brute(segments:&[Segment],pos:&[usize])->usize{
    let mut count=0;
    for i in 0..segments.len(){
        for j in i+1..segments.len(){
            let(a,b)=(&segments[i],&segments[j]);
            if(pos[a.p]<pos[b.p]&&pos[a.q]>pos[b.q])||(pos[a.p]>pos[b.p]&&pos[a.q]<pos[b.q]){
                count+=1;
            }
        }
    }
    count
}
pub fn total(gaps:&[Vec<Segment>],order:&[Vec<usize>],n:usize)->usize{
    let pos=positions(order,n);
    gaps.iter().enumerate().map(|(i,g)|count(g,&pos,order[i+1].len())).sum()
}
pub fn adjacent(v:usize,w:usize,upper:&[Vec<usize>],lower:&[Vec<usize>],pos:&[usize])->usize{
    upper[v].iter().map(|&a|upper[w].iter().filter(|&&b|pos[a]>pos[b]).count()).sum::<usize>()+lower[v].iter().map(|&a|lower[w].iter().filter(|&&b|pos[a]>pos[b]).count()).sum::<usize>()
}

use std::collections::BTreeMap;
use std::fs;
pub const NAMES:[&str;13]=["layering","width","promotion","heuristic","sweeps","node_sep","dummy_sep","layer_gap","direction","sifting","reduce","restarts","seed"];
#[derive(Clone)] pub struct Settings{
    pub values:Vec<String>
}
impl Settings{
    pub fn default()->Self{
        Self{
            values:["longest","4","off","barycenter","12","2","1","3","TB","off","off","0","1"].iter().map(|v|v.to_string()).collect()
        }
    }
    pub fn text(&self,n:&str)->&str{
        &self.values[NAMES.iter().position(|v|*v==n).unwrap()]
    }
    pub fn integer(&self,n:&str)->usize{
        self.text(n).parse().unwrap()
    }
    pub fn on(&self,n:&str)->bool{
        self.text(n)=="on"
    }
    pub fn set(&mut self,n:&str,value:&str)->bool{
        let i=match NAMES.iter().position(|v|*v==n){
            Some(i)=>i,None=>return false
        };
        let words=match n{
            "layering"=>vec!["longest","coffman"],"promotion"|"sifting"|"reduce"=>vec!["on","off"],"heuristic"=>vec!["barycenter","median"],"direction"=>vec!["TB","BT","LR","RL"],_=>Vec::new()
        };
        if !words.is_empty(){
            if !words.contains(&value){
                return false;
            }
            self.values[i]=value.into();
            return true;
        }
        let(lo,hi)=match n{
            "width"=>(1,40),"sweeps"=>(0,50),"node_sep"|"dummy_sep"=>(1,9),"layer_gap"=>(2,9),"restarts"=>(0,9),_ =>(1,2147483646)
        };
        if value.is_empty()||value.len()>10||!value.bytes().all(|c|c.is_ascii_digit()){
            return false;
        }
        if let Ok(v)=value.parse::<usize>(){
            if lo<=v&&v<=hi{
                self.values[i]=v.to_string();
                return true;
            }
        }
        false
    }
}
pub struct Graph{
    pub name:String,
    pub settings:Settings,
    pub nodes:Vec<(usize,String)>,
    pub edges:Vec<(usize,usize)>,
    pub path:Option<(usize,usize)>,
    pub loops:usize,
    pub duplicates:usize,
    pub error:Option<(String,usize)>
}
pub fn read()->Vec<Graph>{
    let mut defaults=Settings::default();
    for line in fs::read_to_string("input/params.txt").unwrap().lines(){
        if !line.is_empty()&&!line.starts_with('#'){
            let a:Vec<_>=line.split(' ').collect();
            defaults.set(a[0],a[1]);
        }
    }
    let mut all=Vec::new();
    let mut current=None;
    let mut nodes:BTreeMap<usize,String>=BTreeMap::new();
    for(i,line)in fs::read_to_string("input/graphs.txt").unwrap().lines().enumerate(){
        if line.is_empty()||line.starts_with('#'){
            continue;
        }
        let a:Vec<_>=line.split(' ').collect();
        if a[0]=="GRAPH"{
            current=Some(Graph{
                name:a[1].into(),
                settings:defaults.clone(),
                nodes:Vec::new(),
                edges:Vec::new(),
                path:None,
                loops:0,
                duplicates:0,
                error:None
            });
            nodes.clear();
            continue;
        }
        let g=current.as_mut().unwrap();
        if a[0]=="END"{
            if g.error.is_none()&&nodes.is_empty(){
                g.error=Some(("no_nodes".into(),i+1));
            }
            g.nodes=nodes.iter().map(|(&id,label)|(id,label.clone())).collect();
            let mut g=current.take().unwrap();
            let numbering:BTreeMap<_,_>=g.nodes.iter().enumerate().map(|(i,(id,_))|(*id,i)).collect();
            if g.error.is_none(){
                g.edges=g.edges.iter().map(|(a,b)|(numbering[a],numbering[b])).collect();
                g.path=g.path.map(|(a,b)|(numbering[&a],numbering[&b]));
            }
            all.push(g);
            continue;
        }
        if g.error.is_some(){
            continue;
        }
        let error=match a[0]{
            "OPTION"=>if g.settings.set(a[1],a[2]){
                None
            }else{
                Some("bad_option")
            },"NODE"=>{
                let id=a[1].parse().unwrap();
                if nodes.contains_key(&id){
                    Some("duplicate_node")
                }else if nodes.len()==40{
                    Some("too_many_nodes")
                }else{
                    nodes.insert(id,a[2].to_string());
                    None
                }
            },"EDGE"=>{
                let u=a[1].parse().unwrap();
                let v=a[2].parse().unwrap();
                if !nodes.contains_key(&u)||!nodes.contains_key(&v){
                    Some("unknown_node")
                }else if u==v{
                    g.loops+=1;
                    None
                }else if g.edges.contains(&(u,v)){
                    g.duplicates+=1;
                    None
                }else{
                    g.edges.push((u,v));
                    None
                }
            },_=>{
                let u=a[1].parse().unwrap();
                let v=a[2].parse().unwrap();
                if !nodes.contains_key(&u)||!nodes.contains_key(&v){
                    Some("unknown_node")
                }else{
                    g.path=Some((u,v));
                    None
                }
            }
        };
        if let Some(error)=error{
            g.error=Some((error.into(),i+1));
        }
    }
    all
}

